UPDATE tmp_import_test_categories
SET organization_id = '99809454-b99a-47a5-a07b-b71e636ef44b';

UPDATE tmp_import_tests
SET organization_id = '99809454-b99a-47a5-a07b-b71e636ef44b';

UPDATE tmp_import_test_packages
SET organization_id = '99809454-b99a-47a5-a07b-b71e636ef44b';

UPDATE public.test_categories AS target
SET description = source.description,
    created_at = LEAST(target.created_at, source.created_at)
FROM tmp_import_test_categories AS source
WHERE target.organization_id = source.organization_id
  AND target.name = source.name;

INSERT INTO public.test_categories (
  id,
  name,
  description,
  created_at,
  organization_id
)
SELECT
  source.id,
  source.name,
  source.description,
  source.created_at,
  source.organization_id
FROM tmp_import_test_categories AS source
LEFT JOIN public.test_categories AS existing
  ON existing.organization_id = source.organization_id
 AND existing.name = source.name
WHERE existing.id IS NULL;

CREATE TEMP TABLE tmp_category_map ON COMMIT DROP AS
SELECT
  source.id AS import_id,
  target.id AS actual_id,
  source.organization_id
FROM tmp_import_test_categories AS source
JOIN public.test_categories AS target
  ON target.organization_id = source.organization_id
 AND target.name = source.name;

UPDATE public.tests AS target
SET category_id = category_map.actual_id,
    name = source.name,
    description = source.description,
    price = source.price,
    created_at = LEAST(target.created_at, source.created_at),
    unit = source.unit,
    normal_range_min = source.normal_range_min,
    normal_range_max = source.normal_range_max,
    normal_range_text = source.normal_range_text,
    sample_type = source.sample_type,
    test_id = source.test_id,
    panel_items = source.panel_items,
    organization_id = source.organization_id
FROM tmp_import_tests AS source
JOIN tmp_category_map AS category_map
  ON category_map.import_id = source.category_id
WHERE target.organization_id = source.organization_id
  AND (
    (source.test_id IS NOT NULL AND target.test_id = source.test_id)
    OR (source.test_id IS NULL AND target.test_id IS NULL AND target.name = source.name)
  );

INSERT INTO public.tests (
  id,
  category_id,
  name,
  description,
  price,
  created_at,
  unit,
  normal_range_min,
  normal_range_max,
  normal_range_text,
  sample_type,
  test_id,
  panel_items,
  organization_id
)
SELECT
  source.id,
  category_map.actual_id,
  source.name,
  source.description,
  source.price,
  source.created_at,
  source.unit,
  source.normal_range_min,
  source.normal_range_max,
  source.normal_range_text,
  source.sample_type,
  source.test_id,
  source.panel_items,
  source.organization_id
FROM tmp_import_tests AS source
JOIN tmp_category_map AS category_map
  ON category_map.import_id = source.category_id
LEFT JOIN public.tests AS existing
  ON existing.organization_id = source.organization_id
 AND (
   (source.test_id IS NOT NULL AND existing.test_id = source.test_id)
   OR (source.test_id IS NULL AND existing.test_id IS NULL AND existing.name = source.name)
 )
WHERE existing.id IS NULL;

CREATE TEMP TABLE tmp_test_map ON COMMIT DROP AS
SELECT
  source.id AS import_id,
  target.id AS actual_id,
  source.organization_id
FROM tmp_import_tests AS source
JOIN public.tests AS target
  ON target.organization_id = source.organization_id
 AND (
   (source.test_id IS NOT NULL AND target.test_id = source.test_id)
   OR (source.test_id IS NULL AND target.test_id IS NULL AND target.name = source.name)
 );

UPDATE public.test_packages AS target
SET description = source.description,
    price = source.price,
    discount_percentage = source.discount_percentage,
    is_active = source.is_active,
    updated_at = GREATEST(target.updated_at, source.updated_at),
    lab_id = source.lab_id,
    organization_id = source.organization_id
FROM tmp_import_test_packages AS source
WHERE target.organization_id = source.organization_id
  AND target.name = source.name;

INSERT INTO public.test_packages (
  id,
  name,
  description,
  price,
  discount_percentage,
  is_active,
  created_at,
  updated_at,
  lab_id,
  organization_id
)
SELECT
  source.id,
  source.name,
  source.description,
  source.price,
  source.discount_percentage,
  source.is_active,
  source.created_at,
  source.updated_at,
  source.lab_id,
  source.organization_id
FROM tmp_import_test_packages AS source
LEFT JOIN public.test_packages AS existing
  ON existing.organization_id = source.organization_id
 AND existing.name = source.name
WHERE existing.id IS NULL;

CREATE TEMP TABLE tmp_package_map ON COMMIT DROP AS
SELECT
  source.id AS import_id,
  target.id AS actual_id,
  source.organization_id
FROM tmp_import_test_packages AS source
JOIN public.test_packages AS target
  ON target.organization_id = source.organization_id
 AND target.name = source.name;

INSERT INTO public.test_package_tests (
  id,
  package_id,
  test_id,
  created_at
)
SELECT
  source.id,
  package_map.actual_id,
  test_map.actual_id,
  source.created_at
FROM tmp_import_test_package_tests AS source
JOIN tmp_package_map AS package_map
  ON package_map.import_id = source.package_id
JOIN tmp_test_map AS test_map
  ON test_map.import_id = source.test_id
LEFT JOIN public.test_package_tests AS existing
  ON existing.package_id = package_map.actual_id
 AND existing.test_id = test_map.actual_id
WHERE existing.id IS NULL;

COMMIT;
